  "overviewHtml": "<p>\n  <img src=\"https://raw.githubusercontent.com/rdlabo-dev/ionic-theme-ios27/ios27-v2.0.3/screenshots/ios27-settings.png\" width=\"32%\" alt=\"iOS 27 テーマ: Liquid Glass 検索バーを備えたライトモードの設定画面\">\n  <img src=\"https://raw.githubusercontent.com/rdlabo-dev/ionic-theme-ios27/ios27-v2.0.3/screenshots/ios27-settings-dark.png\" width=\"32%\" alt=\"iOS 27 テーマ: ダークモードの設定画面\">\n  <img src=\"https://raw.githubusercontent.com/rdlabo-dev/ionic-theme-ios27/ios27-v2.0.3/screenshots/ios27-library.png\" width=\"32%\" alt=\"iOS 27 テーマ: Liquid Glass ボタンとタブバーを備えたライブラリ画面\">\n</p>",
